ui.css:
.tag { border: 5px solid transparent; border-radius: 12px; padding: 7px 16px 7px 10px;
  background: url(aida.png) padding-box, repeating-linear-gradient(-52deg, #c0442c 0 2px, #8c2a1c 2px 3px, #e0704c 3px 4.5px) border-box;
  outline: 2px dashed rgba(124,29,36,.55); outline-offset: -10px;
  box-shadow: 0 4px 0 rgba(50,26,10,.35), 0 6px 14px rgba(20,10,4,.35);
  font-family: 'Mali', 'Grandstander', sans-serif; color: #4a2c1e; }
.bar { width: 216px; height: 18px; border-radius: 3px; background: #ddcba4;
  box-shadow: inset 0 0 0 1px rgba(110,70,30,.45), inset 0 2px 3px rgba(60,30,10,.25); }
.bar-fill { height: 100%; background: url(stitch-red.png) 0 1px/8px 8px; }
.bar-text { font: 800 17px 'Grandstander', sans-serif; color: #7a1c24; text-shadow: 0 1px 0 rgba(255,255,255,.6); }
.hoop { width: 138px; height: 138px; border-radius: 50%; border: 10px solid transparent;
  background: url(aida.png) padding-box, repeating-radial-gradient(circle, #c98f55 0 2px, #b47842 2px 3.5px, #d9a46a 3.5px 5px) border-box;
  box-shadow: inset 0 0 0 1px #7a4c26, 0 0 0 2px #6b4221, 0 0 0 5px #d39c60, 0 0 0 7px #6b4221, 0 8px 18px rgba(20,10,4,.4); }
.stitched-title { font: 900 70px 'Grandstander', sans-serif; background: url(stitch-orange.png) 0 0/8px 8px;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 3px 0 #3a1a0c) drop-shadow(0 0 1px #3a1a0c); }
